/**
 * Run 6 — Owner Decision Matrix (single source). Every owner decision the Construction app waits on, or that the owner
 * has already ruled: the nine policy-register keys P1–P9 (Digit Policy Decision records), every other open owner item
 * recorded in earlier runs (roadmap R4-O/P/Q/T/N, B-xx, DX-x, R2-6, R4-Z …) and every open question of the owner's
 * research contract (contract_index.json `unknowns`). Pure data — no runtime imports — so the generator
 * (scripts/construction-decisions.ts → OWNER_DECISION_MATRIX.md), the crosswalk (`dec` on open items) and
 * ownerDecisions.test.ts read one table.
 *
 * Nothing here is enforced: a recommendation is advice to the owner. The app keeps blocking only the dependent final
 * action until the owner records the decision (P1–P9 on Construction settings → Policy decisions; other items by an
 * explicit owner instruction).
 *
 * Ref syntax (checked by the test): ids = crosswalk contract IDs · doctypes = app or catalog DocTypes · reports = app
 * Script Reports or catalog reports · calcs = `fn:<module under the app>#<export>`.
 */
export type DecisionStatus = "OPEN" | "INTERIM_RULE" | "ILLUSTRATIVE" | "APPROVED";
/** VIRTUAL_CORE = a feature or final action is blocked in the Virtual Core now; FRAPPE_ONLY = the Virtual Core works (or works on a labelled assumption), only real Frappe integration / production needs it; NOT_BLOCKING = quality or UX choice. */
export type Blocking = "VIRTUAL_CORE" | "FRAPPE_ONLY" | "NOT_BLOCKING";
export type Area = "Management & approvals" | "Projects & execution" | "Estimating & tenders" | "Client contracts & claims" | "Subcontracts & measurement" | "Budget & cost"
  | "Procurement & materials" | "Resources & spending" | "Finance & closeout" | "Reports, KPIs & settings" | "Print outputs" | "Cross-cutting" | "Platform (Core)" | "DIGIT integration" | "Brand & experience";
export interface OwnerDecision {
  id: string; title: string; area: Area;
  /** the business question the owner answers */
  question: string;
  /** what the app does today (verified in code) */
  current: string;
  choices: string[];
  /** index into choices */
  recommended: number;
  rationale: string;
  affects: { ids: string[]; doctypes: string[]; reports: string[]; calcs: string[] };
  blocks: Blocking;
  /** exactly what waits on the decision */
  waits: string;
  status: DecisionStatus;
  /** owner ruling (APPROVED) or interim rule (INTERIM_RULE), with its date */
  ruling?: string; ruled_on?: string;
  /** earlier register IDs and research open-question IDs this decision answers */
  legacy: string[];
  /** Digit Policy Decision record key (P1–P9) */
  policy_key?: string;
}
const A = (ids: string[] = [], doctypes: string[] = [], reports: string[] = [], calcs: string[] = []) => ({ ids, doctypes, reports, calcs });
const D = (x: OwnerDecision) => x;

