export const decisionById = (id: string) => OWNER_DECISIONS.find((d) => d.id === id);
/** Open decisions: OPEN, ILLUSTRATIVE (a demo assumption is not a decision) and INTERIM_RULE (an interim rule awaiting the final one). */
export const openDecisions = () => OWNER_DECISIONS.filter((d) => d.status !== "APPROVED");

